from pathlib import Path
import hashlib,json
here=Path(__file__).resolve().parent;work=here.parents[1];game=work/'project/chongqing_godot_v05';asset=game/'assets/district_age'
def digest(p):
    with p.open('rb') as fp:return hashlib.file_digest(fp,'sha256').hexdigest()
def entry(p):return {'file':str(p.relative_to(work)).replace('\\','/'),'sha256':digest(p)}
font=work/'assets_incoming/r20_noto';base=work/'project/chongqing_blender_v05/materials'
record={'build':'R24 build 20 internal','locally_authored':{'maker':'Chongqing district project','work':'Bicycle shed, three bicycles, repair tools, fictional writing, paper atlas, ground masks, cut road meshes and height-derived slope normals','editable':entry(here/'city_and_yards.blend'),'files':[entry(p) for p in sorted(asset.glob('*')) if p.suffix in ('.glb','.png','.json')],'import_settings':[entry(p) for p in sorted(asset.glob('*.import'))],'authoring':[entry(p) for p in sorted(here.glob('*.py')) if p.stem in ['author','roads','supported_runs','road_edge','fork_join','kerb_return','street_mouths','high_approaches','east_passages','west_passage','soft_paving','median_bed','repair_stand','residents','wall_prints','lime_print','paint_lanes','height_tile','slope_tile']]},'existing_materials':[{'creator':'Amal Kumar','title':'Rusty Painted Metal','license':'CC0 1.0','source':'https://polyhaven.com/a/rusty_painted_metal','license_url':'https://polyhaven.com/license','modification':'Local 2K albedo; mapped to a desaturated oxidised zinc roof and enamel coefficients in yard_galvanized.gdshader. No attribution requirement; original source retained.','file':entry(game/'assets/chongqing_district_rusty_painted_metal_diff_2k.jpg'),'metadata':entry(base/'v04_scans/rusty_painted_metal/source_info.json')},{'title':'Existing road, concrete, stone and facade surfaces','provenance':entry(base/'material_provenance.json'),'credits':entry(base/'CREDITS_zh.txt'),'change':'Existing licensed game textures reused on original geometry; no new photograph incorporated.'}],'typeface':{'family':'Noto Sans CJK SC','license':'SIL Open Font License 1.1','source':'https://github.com/notofonts/noto-cjk','source_revision':(font/'source_commit.txt').read_text('utf8').strip(),'source_license':'https://github.com/notofonts/noto-cjk/blob/main/Sans/LICENSE','use':'Rasterised local fictional notices; no new font binaries shipped in the incremental art. Original license and attribution retained beside sources.','files':[entry(font/name) for name in ['LICENSE.txt','NotoSansCJKsc-Regular.otf','NotoSansCJKsc-Bold.otf']]},'geodata':{'source':'https://www.openstreetmap.org/copyright','license':'ODbL 1.0','attribution':'© OpenStreetMap contributors','source_file':entry(work/'project/chongqing_blender_v05/source_data/geo_layout.json'),'local_changes':'Game-specific route deviations stored as separate files; base geodata and HUD attribution preserved.'},'photo_references':{'usage':'Research and visual comparison only. No new image pixels from documentary photographs used in the game.','credit_list':entry(work/'scene_r24/street_photo_study/reference/credits.json')}}
